import gurobipy as gp
from gurobipy import GRB
records = LEGACY_RECORDS
capacity = None
for rec in records:
    vals = rec.get('values', {})
    if 'Capacity' in vals:
        capacity = int(vals['Capacity'])
        break
if capacity is None:
    raise ValueError('No capacity found in LEGACY_RECORDS.')
products = []
profit = {}
weight = {}
for rec in records:
    vals = rec.get('values', {})
    if 'ProductName' in vals and 'Value' in vals and ('Weight' in vals):
        name = vals['ProductName']
        products.append(name)
        profit[name] = int(vals['Value'])
        weight[name] = int(vals['Weight'])
if not products or len(profit) != len(products) or len(weight) != len(products):
    raise ValueError('Missing product data in LEGACY_RECORDS.')
m = gp.Model('Car_Inventory_Optimization')
x = m.addVars(products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((profit[i] * x[i] for i in products)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in products)) <= capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')